/**
 * The npm packages APIX recognises as the Hedera SDK in a user's project.
 *
 * Generated code uses @hiero-ledger/sdk since APIX 2.2.0. Apps generated by
 * 2.1.x use @hashgraph/sdk (the SDK's name before it moved to Hiero) and keep
 * working, so detection accepts both and prefers the current one.
 */
export const HEDERA_SDK_PACKAGE = '@hiero-ledger/sdk';
export const LEGACY_HEDERA_SDK_PACKAGE = '@hashgraph/sdk';
export const HEDERA_SDK_PACKAGES = [HEDERA_SDK_PACKAGE, LEGACY_HEDERA_SDK_PACKAGE] as const;

export interface DeclaredHederaSdk {
  name: (typeof HEDERA_SDK_PACKAGES)[number];
  range: string;
}

export function isHederaSdkPackage(name: string): boolean {
  return (HEDERA_SDK_PACKAGES as readonly string[]).includes(name);
}

/** The Hedera SDK a package.json declares (dependencies or devDependencies), current name first */
export function declaredHederaSdk(packageJson: { dependencies?: Record<string, string>; devDependencies?: Record<string, string> } | null | undefined): DeclaredHederaSdk | undefined {
  for (const name of HEDERA_SDK_PACKAGES) {
    const range = packageJson?.dependencies?.[name] || packageJson?.devDependencies?.[name];
    if (range) return { name, range };
  }
  return undefined;
}
